=head2 Google::Bigtable::Admin::V2::BigtableTableAdmin::CreateTableRequest

Request message for
[google.bigtable.admin.v2.BigtableTableAdmin.CreateTable][google.bigtable.admin.v2.BigtableTableAdmin.CreateTable]

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->parent() >> / C<< $msg->parent($value) >>

Type: C<String>

Required. The unique name of the instance in which to create the table.
Values are of the form `projects/{project}/instances/{instance}`.

=item * C<< $msg->table_id() >> / C<< $msg->table_id($value) >>

Type: C<String>

Required. The name by which the new table should be referred to within the
parent instance, e.g., `foobar` rather than `{parent}/tables/foobar`.
Maximum 50 characters.

=item * C<< $msg->table() >> / C<< $msg->table($value) >>

Type: C<Message> (L<Google::Bigtable::Admin::V2::Table::Table>)

Required. The Table to create.

=item * C<< $msg->initial_splits() >> / C<< $msg->initial_splits($value) >>

Type: C<Message> (L<Google::Bigtable::Admin::V2::BigtableTableAdmin::CreateTableRequest::Split>)

The optional list of row keys that will be used to initially split the
table into several tablets (tablets are similar to HBase regions).
Given two split keys, `s1` and `s2`, three tablets will be created,
spanning the key ranges: `[, s1), [s1, s2), [s2, )`.

Example:

* Row keys := `["a", "apple", "custom", "customer_1", "customer_2",`
               `"other", "zz"]`
* initial_split_keys := `["apple", "customer_1", "customer_2", "other"]`
* Key assignment:
    - Tablet 1 `[, apple)                => {"a"}.`
    - Tablet 2 `[apple, customer_1)      => {"apple", "custom"}.`
    - Tablet 3 `[customer_1, customer_2) => {"customer_1"}.`
    - Tablet 4 `[customer_2, other)      => {"customer_2"}.`
    - Tablet 5 `[other, )                => {"other", "zz"}.`

=back

