=head2 Google::Bigtable::Admin::V2::BigtableTableAdmin::CopyBackupRequest

The request for
[CopyBackup][google.bigtable.admin.v2.BigtableTableAdmin.CopyBackup].

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->parent() >> / C<< $msg->parent($value) >>

Type: C<String>

Required. The name of the destination cluster that will contain the backup
copy. The cluster must already exist. Values are of the form:
`projects/{project}/instances/{instance}/clusters/{cluster}`.

=item * C<< $msg->backup_id() >> / C<< $msg->backup_id($value) >>

Type: C<String>

Required. The id of the new backup. The `backup_id` along with `parent`
are combined as {parent}/backups/{backup_id} to create the full backup
name, of the form:
`projects/{project}/instances/{instance}/clusters/{cluster}/backups/{backup_id}`.
This string must be between 1 and 50 characters in length and match the
regex [_a-zA-Z0-9][-_.a-zA-Z0-9]*.

=item * C<< $msg->source_backup() >> / C<< $msg->source_backup($value) >>

Type: C<String>

Required. The source backup to be copied from.
The source backup needs to be in READY state for it to be copied.
Copying a copied backup is not allowed.
Once CopyBackup is in progress, the source backup cannot be deleted or
cleaned up on expiration until CopyBackup is finished.
Values are of the form:
`projects/<project>/instances/<instance>/clusters/<cluster>/backups/<backup>`.

=item * C<< $msg->expire_time() >> / C<< $msg->expire_time($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

Required. Required. The expiration time of the copied backup with
microsecond granularity that must be at least 6 hours and at most 30 days
from the time the request is received. Once the `expire_time` has
passed, Cloud Bigtable will delete the backup and free the resources used
by the backup.

=back

